CREATE TABLE "project_submission_assets" (
	"id" uuid PRIMARY KEY NOT NULL,
	"project_id" text NOT NULL,
	"owner_id" uuid NOT NULL,
	"purpose" text NOT NULL,
	"name" text NOT NULL,
	"storage_name" text NOT NULL,
	"media_type" text NOT NULL,
	"size" integer NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "project_submission_assets_storage_name_unique" UNIQUE("storage_name"),
	CONSTRAINT "project_submission_asset_purpose" CHECK ("project_submission_assets"."purpose" IN ('cover','screenshot','document')),
	CONSTRAINT "project_submission_asset_size" CHECK ("project_submission_assets"."size">0)
);
--> statement-breakpoint
CREATE TABLE "project_submission_versions" (
	"id" uuid PRIMARY KEY NOT NULL,
	"project_id" text NOT NULL,
	"number" integer NOT NULL,
	"payload" jsonb NOT NULL,
	"submitted_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "project_submission_version_positive" CHECK ("project_submission_versions"."number">0)
);
--> statement-breakpoint
CREATE TABLE "submitted_projects" (
	"id" text PRIMARY KEY NOT NULL,
	"source" text NOT NULL,
	"owner_id" uuid,
	"creation_key" uuid,
	"event_id" text,
	"draft" jsonb,
	"draft_revision" integer DEFAULT 0 NOT NULL,
	"submitted_revision" integer DEFAULT 0 NOT NULL,
	"revision" integer DEFAULT 1 NOT NULL,
	"review_state" text,
	"public_note" text,
	"internal_note" text,
	"publication_state" text DEFAULT 'unpublished' NOT NULL,
	"live" jsonb,
	"live_revision" integer,
	"consent_revoked" boolean DEFAULT false NOT NULL,
	"published_at" timestamp with time zone,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "submitted_project_source" CHECK (("submitted_projects"."source"='user' AND "submitted_projects"."owner_id" IS NOT NULL AND "submitted_projects"."draft" IS NOT NULL AND "submitted_projects"."creation_key" IS NOT NULL) OR ("submitted_projects"."source"='demo' AND "submitted_projects"."owner_id" IS NULL AND "submitted_projects"."draft" IS NULL)),
	CONSTRAINT "submitted_project_review" CHECK ("submitted_projects"."review_state" IS NULL OR "submitted_projects"."review_state" IN ('pending','approved','rejected')),
	CONSTRAINT "submitted_project_publication" CHECK ("submitted_projects"."publication_state" IN ('unpublished','published','withdrawn')),
	CONSTRAINT "submitted_project_live" CHECK ("submitted_projects"."publication_state"<>'published' OR ("submitted_projects"."live" IS NOT NULL AND "submitted_projects"."live_revision" IS NOT NULL AND NOT "submitted_projects"."consent_revoked")),
	CONSTRAINT "submitted_project_versions" CHECK ("submitted_projects"."revision">0 AND "submitted_projects"."draft_revision">=0 AND "submitted_projects"."submitted_revision">=0)
);
--> statement-breakpoint
ALTER TABLE "project_submission_assets" ADD CONSTRAINT "project_submission_assets_project_id_submitted_projects_id_fk" FOREIGN KEY ("project_id") REFERENCES "public"."submitted_projects"("id") ON DELETE restrict ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "project_submission_assets" ADD CONSTRAINT "project_submission_assets_owner_id_users_id_fk" FOREIGN KEY ("owner_id") REFERENCES "public"."users"("id") ON DELETE restrict ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "project_submission_versions" ADD CONSTRAINT "project_submission_versions_project_id_submitted_projects_id_fk" FOREIGN KEY ("project_id") REFERENCES "public"."submitted_projects"("id") ON DELETE restrict ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "submitted_projects" ADD CONSTRAINT "submitted_projects_owner_id_users_id_fk" FOREIGN KEY ("owner_id") REFERENCES "public"."users"("id") ON DELETE restrict ON UPDATE no action;--> statement-breakpoint
CREATE INDEX "project_submission_assets_project_idx" ON "project_submission_assets" USING btree ("project_id");--> statement-breakpoint
CREATE UNIQUE INDEX "project_submission_version_unique" ON "project_submission_versions" USING btree ("project_id","number");--> statement-breakpoint
CREATE UNIQUE INDEX "submitted_project_creation_unique" ON "submitted_projects" USING btree ("owner_id","creation_key");--> statement-breakpoint
CREATE INDEX "submitted_project_owner_idx" ON "submitted_projects" USING btree ("owner_id","created_at");--> statement-breakpoint
CREATE INDEX "submitted_project_management_idx" ON "submitted_projects" USING btree ("publication_state","review_state","updated_at");
