('idea-atlas','demo','demo','published','{"id":"idea-atlas","name":{"zh":"灵感地图","en":"Idea Atlas"},"introduction":{"zh":"把散落的灵感连接起来，沿着好奇心寻找下一个值得动手的问题。","en":"Connect scattered ideas and follow your curiosity toward the next question worth building for."},"category":"software","eventId":"demo","tags":[{"zh":"知识连接","en":"Knowledge"},{"zh":"可视化","en":"Visualization"},{"zh":"探索","en":"Discovery"},{"zh":"创作工具","en":"Creative tools"}],"creator":{"zh":"好奇心工坊 · 示例创作者","en":"Curiosity studio · demo creator"},"cover":"/projects/atlas.svg","publishedAt":"2026-10-09T08:00:00+08:00","published":true,"demo":true,"details":{"description":[{"zh":"灵感地图 · 项目概念\n把散落的灵感连接起来，沿着好奇心寻找下一个值得动手的问题。","en":"Idea Atlas · Concept\nConnect scattered ideas and follow your curiosity toward the next question worth building for."},{"zh":"从线索到问题\n将片段归入主题，以图谱呈现联系；创作者可以逐步标记值得验证的问题，而不是急于生成结论。","en":"From clues to questions\nGroup fragments into themes and map their connections. Mark questions worth testing instead of rushing to conclusions."},{"zh":"验证方向与当前阶段\n先验证核心体验、可访问性和隐私边界，再根据真实反馈迭代。本项目是原创演示概念，图像为示意，不代表已实现、已获奖或可运行产品。你可以通过评论提出问题和建议。","en":"Validation and current stage\nTest the core experience, accessibility and privacy boundaries before iterating with feedback. This original demo concept and its illustrations do not claim a working or awarded product. Questions and suggestions are welcome."}],"media":[{"src":"/projects/atlas.svg","alt":{"zh":"灵感地图概念封面","en":"Idea Atlas concept cover"}},{"src":"/projects/interaction-map.svg","alt":{"zh":"灵感地图体验验证流程示意","en":"Idea Atlas experience validation diagram"}}],"links":[]}}'::jsonb,0,'2026-10-09T08:00:00+08:00','2026-10-09T08:00:00+08:00','2026-10-09T08:00:00+08:00'),
('pocket-garden','demo',NULL,'published','{"id":"pocket-garden","name":{"zh":"口袋花园","en":"Pocket Garden"},"introduction":{"zh":"一盏会回应环境的小灯，让桌面上的植物与日常生活轻轻对话。","en":"A small light that responds to its surroundings, connecting a desktop plant with everyday life."},"category":"hardware","eventId":null,"tags":[{"zh":"环境感知","en":"Sensors"},{"zh":"日常设计","en":"Everyday design"}],"creator":{"zh":"好奇心工坊 · 示例创作者","en":"Curiosity studio · demo creator"},"cover":"/projects/garden.svg","publishedAt":"2026-10-09T08:00:00+08:00","published":true,"demo":true,"details":{"description":[{"zh":"口袋花园 · 项目概念\n一盏会回应环境的小灯，让桌面上的植物与日常生活轻轻对话。","en":"Pocket Garden · Concept\nA small light that responds to its surroundings, connecting a desktop plant with everyday life."},{"zh":"把环境变成轻柔的提示\n设想通过环境传感与灯光反馈，让植物照护成为可观察的日常仪式，不替代专业园艺判断。","en":"A gentler environmental signal\nA concept connecting ambient sensing with light feedback, making plant care an observable daily ritual."},{"zh":"验证方向与当前阶段\n先验证核心体验、可访问性和隐私边界，再根据真实反馈迭代。本项目是原创演示概念，图像为示意，不代表已实现、已获奖或可运行产品。你可以通过评论提出问题和建议。","en":"Validation and current stage\nTest the core experience, accessibility and privacy boundaries before iterating with feedback. This original demo concept and its illustrations do not claim a working or awarded product. Questions and suggestions are welcome."}],"media":[{"src":"/projects/garden.svg","alt":{"zh":"口袋花园概念封面","en":"Pocket Garden concept cover"}},{"src":"/projects/interaction-map.svg","alt":{"zh":"口袋花园体验验证流程示意","en":"Pocket Garden experience validation diagram"}}],"links":[]}}'::jsonb,0,'2026-10-09T08:00:00+08:00','2026-10-09T08:00:00+08:00','2026-10-09T08:00:00+08:00'),
('echo-island','demo','demo','published','{"id":"echo-island","name":{"zh":"回声岛","en":"Echo Island"},"introduction":{"zh":"用声音探索一座看不见的岛屿，每一次倾听都是一条新的路径。","en":"Explore an unseen island through sound. Every moment of listening opens another path."},"category":"game","eventId":"demo","tags":[{"zh":"声音","en":"Sound"},{"zh":"探索游戏","en":"Exploration"}],"creator":{"zh":"好奇心工坊 · 示例创作者","en":"Curiosity studio · demo creator"},"cover":"/projects/echo.svg","publishedAt":"2026-10-08T08:00:00+08:00","published":true,"demo":true,"details":{"description":[{"zh":"回声岛 · 项目概念\n用声音探索一座看不见的岛屿，每一次倾听都是一条新的路径。","en":"Echo Island · Concept\nExplore an unseen island through sound. Every moment of listening opens another path."},{"zh":"以倾听发现路径\n让玩家通过声源方位和回声变化探索空间；可访问性与音量控制是设计验证的重要部分。","en":"Find a path by listening\nExplore space through direction and changing echoes, with accessibility and volume control central to testing."},{"zh":"验证方向与当前阶段\n先验证核心体验、可访问性和隐私边界，再根据真实反馈迭代。本项目是原创演示概念，图像为示意，不代表已实现、已获奖或可运行产品。你可以通过评论提出问题和建议。","en":"Validation and current stage\nTest the core experience, accessibility and privacy boundaries before iterating with feedback. This original demo concept and its illustrations do not claim a working or awarded product. Questions and suggestions are welcome."}],"media":[{"src":"/projects/echo.svg","alt":{"zh":"回声岛概念封面","en":"Echo Island concept cover"}},{"src":"/projects/interaction-map.svg","alt":{"zh":"回声岛体验验证流程示意","en":"Echo Island experience validation diagram"}}],"links":[]}}'::jsonb,0,'2026-10-08T08:00:00+08:00','2026-10-08T08:00:00+08:00','2026-10-08T08:00:00+08:00'),
('light-notes','demo','past-demo','published','{"id":"light-notes","name":{"zh":"光的手记","en":"Notes of Light"},"introduction":{"zh":"用抽象影像记录一天的光线，让时间变成一段可以观看的诗。","en":"Record a day of light as abstract moving images, turning time into a visual poem."},"category":"aigc","eventId":"past-demo","tags":[{"zh":"生成影像","en":"Generative film"},{"zh":"光影","en":"Light"}],"creator":{"zh":"好奇心工坊 · 示例创作者","en":"Curiosity studio · demo creator"},"cover":"/projects/light.svg","publishedAt":"2026-10-07T08:00:00+08:00","published":true,"demo":true,"details":{"description":[{"zh":"光的手记 · 项目概念\n用抽象影像记录一天的光线，让时间变成一段可以观看的诗。","en":"Notes of Light · Concept\nRecord a day of light as abstract moving images, turning time into a visual poem."},{"zh":"让记录保留现场感\n用简单的光线与文字关联记录时刻，探索情境如何帮助回忆，同时减少多余的界面操作。","en":"Keep the context of a moment\nAssociate light and text with moments, exploring contextual memory with fewer interface actions."},{"zh":"验证方向与当前阶段\n先验证核心体验、可访问性和隐私边界，再根据真实反馈迭代。本项目是原创演示概念，图像为示意，不代表已实现、已获奖或可运行产品。你可以通过评论提出问题和建议。","en":"Validation and current stage\nTest the core experience, accessibility and privacy boundaries before iterating with feedback. This original demo concept and its illustrations do not claim a working or awarded product. Questions and suggestions are welcome."}],"media":[{"src":"/projects/light.svg","alt":{"zh":"光的手记概念封面","en":"Notes of Light concept cover"}},{"src":"/projects/interaction-map.svg","alt":{"zh":"光的手记体验验证流程示意","en":"Notes of Light experience validation diagram"}}],"links":[]}}'::jsonb,0,'2026-10-07T08:00:00+08:00','2026-10-07T08:00:00+08:00','2026-10-07T08:00:00+08:00'),
('shared-table','demo',NULL,'published','{"id":"shared-table","name":{"zh":"共创一桌","en":"Shared Table"},"introduction":{"zh":"一套帮助陌生人交换想法的桌面卡片，从一个好问题开始一场讨论。","en":"A set of tabletop prompts for exchanging ideas with new people. Start a conversation with one good question."},"category":"other","eventId":null,"tags":[{"zh":"共创","en":"Co-creation"},{"zh":"交流","en":"Conversation"}],"creator":{"zh":"好奇心工坊 · 示例创作者","en":"Curiosity studio · demo creator"},"cover":"/projects/table.svg","publishedAt":"2026-10-06T08:00:00+08:00","published":true,"demo":true,"details":{"description":[{"zh":"共创一桌 · 项目概念\n一套帮助陌生人交换想法的桌面卡片，从一个好问题开始一场讨论。","en":"Shared Table · Concept\nA set of tabletop prompts for exchanging ideas with new people. Start a conversation with one good question."},{"zh":"为相遇创造空间\n以共享桌面活动为线索连接参与者，强调明确的参与意愿与可退出机制，避免制造社交压力。","en":"Make room for connection\nA shared-table concept built around explicit participation and easy opt-out, without social pressure."},{"zh":"验证方向与当前阶段\n先验证核心体验、可访问性和隐私边界，再根据真实反馈迭代。本项目是原创演示概念，图像为示意，不代表已实现、已获奖或可运行产品。你可以通过评论提出问题和建议。","en":"Validation and current stage\nTest the core experience, accessibility and privacy boundaries before iterating with feedback. This original demo concept and its illustrations do not claim a working or awarded product. Questions and suggestions are welcome."}],"media":[{"src":"/projects/table.svg","alt":{"zh":"共创一桌概念封面","en":"Shared Table concept cover"}},{"src":"/projects/interaction-map.svg","alt":{"zh":"共创一桌体验验证流程示意","en":"Shared Table experience validation diagram"}}],"links":[]}}'::jsonb,0,'2026-10-06T08:00:00+08:00','2026-10-06T08:00:00+08:00','2026-10-06T08:00:00+08:00'),
('quiet-clock','demo','upcoming-demo','published','{"id":"quiet-clock","name":{"zh":"安静时钟","en":"Quiet Clock"},"introduction":{"zh":"用缓慢变化的色彩提示时间，为专注和休息留出温和的节奏。","en":"Mark time with gradually shifting colors, giving focus and rest a gentler rhythm."},"category":"hardware","eventId":"upcoming-demo","tags":[{"zh":"专注","en":"Focus"},{"zh":"交互设计","en":"Interaction"}],"creator":{"zh":"好奇心工坊 · 示例创作者","en":"Curiosity studio · demo creator"},"cover":"/projects/clock.svg","publishedAt":"2026-10-05T08:00:00+08:00","published":true,"demo":true,"details":{"description":[{"zh":"安静时钟 · 项目概念\n用缓慢变化的色彩提示时间，为专注和休息留出温和的节奏。","en":"Quiet Clock · Concept\nMark time with gradually shifting colors, giving focus and rest a gentler rhythm."},{"zh":"重新理解时间\n将紧迫的数字倒计时转为柔和的阶段提示，帮助使用者安排专注与休息；这是一项交互实验。","en":"Reframing time\nAn interaction experiment replacing urgent countdowns with gentle phase cues for focus and rest."},{"zh":"验证方向与当前阶段\n先验证核心体验、可访问性和隐私边界，再根据真实反馈迭代。本项目是原创演示概念，图像为示意，不代表已实现、已获奖或可运行产品。你可以通过评论提出问题和建议。","en":"Validation and current stage\nTest the core experience, accessibility and privacy boundaries before iterating with feedback. This original demo concept and its illustrations do not claim a working or awarded product. Questions and suggestions are welcome."}],"media":[{"src":"/projects/clock.svg","alt":{"zh":"安静时钟概念封面","en":"Quiet Clock concept cover"}},{"src":"/projects/interaction-map.svg","alt":{"zh":"安静时钟体验验证流程示意","en":"Quiet Clock experience validation diagram"}}],"links":[]}}'::jsonb,0,'2026-10-05T08:00:00+08:00','2026-10-05T08:00:00+08:00','2026-10-05T08:00:00+08:00'),
