('tiny-orbits','demo','upcoming-demo','published','{"id":"tiny-orbits","name":{"zh":"小小轨道","en":"Tiny Orbits"},"introduction":{"zh":"通过调整星体的轨道解决谜题，体验平衡与变化之间的微妙关系。","en":"Solve puzzles by adjusting small celestial orbits and explore the relationship between balance and change."},"category":"game","eventId":"upcoming-demo","tags":[{"zh":"解谜","en":"Puzzle"},{"zh":"轨道","en":"Orbits"}],"creator":{"zh":"好奇心工坊 · 示例创作者","en":"Curiosity studio · demo creator"},"cover":"/projects/orbit.svg","publishedAt":"2026-10-03T08:00:00+08:00","published":true,"demo":true,"details":{"description":[{"zh":"小小轨道 · 项目概念\n通过调整星体的轨道解决谜题，体验平衡与变化之间的微妙关系。","en":"Tiny Orbits · Concept\nSolve puzzles by adjusting small celestial orbits and explore the relationship between balance and change."},{"zh":"小小的轨道实验\n通过改变引力与初始方向观察轨迹，学习系统中的微小变化如何影响结果；强调可撤销的尝试和直观反馈。","en":"Small orbital experiments\nAdjust gravity and starting direction to observe changing paths, exploring how small choices shape a system through reversible experiments."},{"zh":"验证方向与当前阶段\n先验证核心体验、可访问性和隐私边界，再根据真实反馈迭代。本项目是原创演示概念，图像为示意，不代表已实现、已获奖或可运行产品。你可以通过评论提出问题和建议。","en":"Validation and current stage\nTest the core experience, accessibility and privacy boundaries before iterating with feedback. This original demo concept and its illustrations do not claim a working or awarded product. Questions and suggestions are welcome."}],"media":[{"src":"/projects/orbit.svg","alt":{"zh":"小小轨道概念封面","en":"Tiny Orbits concept cover"}},{"src":"/projects/interaction-map.svg","alt":{"zh":"小小轨道体验验证流程示意","en":"Tiny Orbits experience validation diagram"}}],"links":[]}}'::jsonb,0,'2026-10-03T08:00:00+08:00','2026-10-03T08:00:00+08:00','2026-10-03T08:00:00+08:00'),
