CREATE FUNCTION project_versions_immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Submitted project versions are immutable'; END; $$;
--> statement-breakpoint
CREATE TRIGGER project_versions_immutable BEFORE UPDATE OR DELETE ON project_submission_versions FOR EACH ROW EXECUTE FUNCTION project_versions_immutable();
